import sys

def main():
    s = sys.stdin.read().split()[0]
    match = {')': '(', ']': '[', '}': '{'}
    stack = []
    ok = True
    for ch in s:
        if ch in match:
            if not stack or stack[-1] != match[ch]:
                ok = False
                break
            stack.pop()
        else:
            stack.append(ch)
    if stack:
        ok = False
    print('true' if ok else 'false')

main()

